async function serve() {
  const server = http.createServer((req,res) => {res.setHeader('cache-control','no-store');res.setHeader('content-type',req.url==='/core.js'?'application/javascript':'text/html;charset=utf-8');res.end(req.url==='/core.js'?core:fixture);});
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  return {server,url:`http://127.0.0.1:${server.address().port}`};
}
